const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'before', 'but', 'by',
  'do', 'does', 'for', 'from', 'how', 'if', 'in', 'into', 'is', 'it',
  'of', 'on', 'or', 'the', 'this', 'to', 'was', 'what', 'when',
  'while', 'with',
]);

const ELIGIBLE_DOCUMENT_IDS = new Set([
  'RUNBOOK-DEPLOY-001',
  'RUNBOOK-DB-001',
]);

const normalize = (text) => {
  const tokens = String(text ?? '').toLowerCase().match(/[a-z0-9]+/g) ?? [];

  return new Set(
    tokens.filter(
      (token) => token.length >= 3 && !STOP_WORDS.has(token),
    ),
  );
};

const question = $json.question;
const documents = $json.documents;

if (typeof question !== 'string' || question.trim() === '') {
  throw new Error('Retrieval input requires a nonempty question.');
}

if (!Array.isArray(documents)) {
  throw new Error('Retrieval input requires a documents array.');
}

const policyDocument = documents.find(
  (document) => document.document_id === 'POLICY-AI-001',
);

if (!policyDocument) {
  throw new Error('Required policy document POLICY-AI-001 is missing.');
}

const questionTokens = normalize(question);

const retrievedDocuments = documents
  .filter((document) =>
    ELIGIBLE_DOCUMENT_IDS.has(document.document_id),
  )
  .map((document) => {
    const documentTokens = normalize(document.content);
    const score = [...questionTokens].filter((token) =>
      documentTokens.has(token),
    ).length;

    return {
      document_id: document.document_id,
      title: document.title,
      content: document.content,
      score,
    };
  })
  .filter((document) => document.score >= 2)
  .sort((left, right) => {
    if (right.score !== left.score) {
      return right.score - left.score;
    }

    if (left.document_id < right.document_id) {
      return -1;
    }

    if (left.document_id > right.document_id) {
      return 1;
    }

    return 0;
  })
  .slice(0, 2);

return {
  json: {
    question_id: $json.question_id,
    question,
    retrieval_status:
      retrievedDocuments.length > 0 ? 'evidence_found' : 'no_evidence',
    policy_document: policyDocument,
    retrieved_documents: retrievedDocuments,
  },
};

