const failClosed = (reasons) => ({
  json: {
    validation_status: 'rejected',
    trusted: false,
    rejection_reasons: reasons,
    answer_status: 'unknown',
    answer: 'Model answer rejected by deterministic grounding validation.',
    citations: [],
    requires_human_review: true,
  },
});

const retrievalResult =
  $('Retrieve Evidence Deterministically').item.json;

const retrievedDocumentIds = new Set(
  (retrievalResult.retrieved_documents ?? []).map(
    (document) => document.document_id,
  ),
);

const outputText = ($json.output ?? [])
  .flatMap((outputItem) => outputItem.content ?? [])
  .find((contentItem) => contentItem.type === 'output_text')
  ?.text;

if (typeof outputText !== 'string' || outputText.trim() === '') {
  return failClosed(['missing_output_text']);
}

let modelResult;

try {
  modelResult = JSON.parse(outputText);
} catch {
  return failClosed(['invalid_output_json']);
}

if (
  modelResult === null ||
  typeof modelResult !== 'object' ||
  Array.isArray(modelResult)
) {
  return failClosed(['output_must_be_an_object']);
}

const rejectionReasons = [];

const requiredFields = [
  'answer_status',
  'answer',
  'citations',
  'requires_human_review',
];

const actualFields = Object.keys(modelResult).sort();
const expectedFields = [...requiredFields].sort();

if (JSON.stringify(actualFields) !== JSON.stringify(expectedFields)) {
  rejectionReasons.push('schema_fields_mismatch');
}

if (!['grounded', 'unknown'].includes(modelResult.answer_status)) {
  rejectionReasons.push('invalid_answer_status');
}

if (typeof modelResult.answer !== 'string') {
  rejectionReasons.push('answer_must_be_a_string');
}

if (!Array.isArray(modelResult.citations)) {
  rejectionReasons.push('citations_must_be_an_array');
}

if (modelResult.requires_human_review !== true) {
  rejectionReasons.push('human_review_must_be_true');
}

if (Array.isArray(modelResult.citations)) {
  const citationsAreStrings = modelResult.citations.every(
    (citation) => typeof citation === 'string',
  );

  if (!citationsAreStrings) {
    rejectionReasons.push('citations_must_contain_only_strings');
  }

  const uniqueCitations = new Set(modelResult.citations);

  if (uniqueCitations.size !== modelResult.citations.length) {
    rejectionReasons.push('duplicate_citations');
  }

  for (const citation of modelResult.citations) {
    if (!retrievedDocumentIds.has(citation)) {
      rejectionReasons.push(`citation_not_retrieved:${citation}`);
    }
  }

  if (modelResult.citations.includes('POLICY-AI-001')) {
    rejectionReasons.push('policy_document_used_as_factual_citation');
  }
}

if (modelResult.answer_status === 'grounded') {
  if (
    typeof modelResult.answer !== 'string' ||
    modelResult.answer.trim() === ''
  ) {
    rejectionReasons.push('grounded_answer_must_be_nonempty');
  }

  if (
    !Array.isArray(modelResult.citations) ||
    modelResult.citations.length === 0
  ) {
    rejectionReasons.push('grounded_answer_requires_citations');
  }

  if (retrievalResult.retrieval_status !== 'evidence_found') {
    rejectionReasons.push('grounded_answer_without_retrieved_evidence');
  }
}

if (modelResult.answer_status === 'unknown') {
  if (modelResult.answer !== 'Insufficient approved evidence.') {
    rejectionReasons.push('unknown_answer_text_mismatch');
  }

  if (
    !Array.isArray(modelResult.citations) ||
    modelResult.citations.length !== 0
  ) {
    rejectionReasons.push('unknown_answer_requires_empty_citations');
  }
}

if (
  retrievalResult.retrieval_status === 'no_evidence' &&
  modelResult.answer_status !== 'unknown'
) {
  rejectionReasons.push('no_evidence_must_return_unknown');
}

const prohibitedActionClaims = [
  /rollback was completed/i,
  /rollback has been completed/i,
  /rollback completed/i,
  /rolled back successfully/i,
  /automatically rolled back/i,
];

if (
  typeof modelResult.answer === 'string' &&
  prohibitedActionClaims.some((pattern) =>
    pattern.test(modelResult.answer),
  )
) {
  rejectionReasons.push('unsupported_operational_action_claim');
}

if (rejectionReasons.length > 0) {
  return failClosed([...new Set(rejectionReasons)]);
}

return {
  json: {
    validation_status: 'accepted',
    trusted: true,
    rejection_reasons: [],
    answer_status: modelResult.answer_status,
    answer: modelResult.answer,
    citations: modelResult.citations,
    requires_human_review: true,
    retrieved_document_ids: [...retrievedDocumentIds],
  },
};
